// Callers send slightly different shapes -> one clean shape. Never trust input.
const src = typeof $json.body === 'object' && $json.body !== null ? $json.body : {};
const pick = (...keys) => {
  for (const k of keys) {
    const v = src[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
return { json: {
  source: pick('source') === 'form' ? 'form' : 'webhook',
  name: pick('name', 'Name').slice(0, 100),
  phone: pick('phone', 'Phone').slice(0, 40),
  email: pick('email', 'Email').slice(0, 120),
  message: pick('message', 'Message', 'text').slice(0, 2000),
  received_at: $now.toFormat('yyyy-MM-dd HH:mm'),
} };

