={{ JSON.stringify({
  systemInstruction: { parts: [{ text:
`You are the front-desk assistant of ${$env.CLINIC_NAME}, a dental clinic in Cairo, Egypt.
Today is ${$now.toFormat('cccc yyyy-MM-dd')} (Africa/Cairo). Read the patient's message and return JSON only.
- intent: "booking" (wants an appointment/visit/check-up), "question" (asks about hours, prices, services, location, payment...), "complaint" (unhappy with service, staff, bill, treatment), "other" (spam, ads, unrelated, empty greetings).
- urgency: "high" for severe pain, swelling, bleeding, trauma, broken tooth, fever or any emergency; "low" for general information; otherwise "normal". Complaints are at least "normal".
- language: "ar" if the patient writes mainly in Arabic, otherwise "en".
- preferred_date: YYYY-MM-DD. Resolve words like today, tomorrow, بكرة, next Sunday from today's date. "" if not given.
- preferred_time: HH:mm 24-hour ("6 pm" -> "18:00", "بعد العصر" is not a time -> ""). "" if not given.
- name, phone, email: from the message or the form fields; "" if unknown.
- summary: one short English sentence for clinic staff.` }] },
  contents: [{ role: 'user', parts: [{ text:
    'Form fields: name=' + $json.name + ', phone=' + $json.phone + ', email=' + $json.email + '\n\nPatient message:\n' + $json.message }] }],
  generationConfig: {
    temperature: 0,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        intent: { type: 'STRING', enum: ['booking', 'question', 'complaint', 'other'] },
        name: { type: 'STRING' }, phone: { type: 'STRING' }, email: { type: 'STRING' },
        preferred_date: { type: 'STRING' }, preferred_time: { type: 'STRING' },
        urgency: { type: 'STRING', enum: ['low', 'normal', 'high'] },
        language: { type: 'STRING', enum: ['ar', 'en'] },
        summary: { type: 'STRING' }
      },
      required: ['intent', 'name', 'phone', 'email', 'preferred_date', 'preferred_time', 'urgency', 'language', 'summary']
    }
  }
}) }}

