// Parse and validate the AI JSON. Never trust it blindly.
const input = $('Has a message?').item.json;
const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
let ai = null;
try { ai = JSON.parse(raw); } catch (e) { ai = null; }
const oneOf = (v, list) => list.includes(v);
const valid = !!ai && typeof ai === 'object'
  && oneOf(ai.intent, ['booking', 'question', 'complaint', 'other'])
  && oneOf(ai.urgency, ['low', 'normal', 'high'])
  && oneOf(ai.language, ['ar', 'en'])
  && typeof ai.summary === 'string';
const FALLBACK = false;
if (!valid && !FALLBACK) return { json: { valid: false } };
const a = valid ? ai : { intent: 'other', urgency: 'normal', summary: 'AI could not read this message (needs manual review).',
  language: /[؀-ۿ]/.test(input.message) ? 'ar' : 'en' };
const str = v => (typeof v === 'string' ? v.trim() : '');
const date = /^\d{4}-\d{2}-\d{2}$/.test(str(a.preferred_date)) ? str(a.preferred_date) : '';
const time = /^([01]\d|2[0-3]):[0-5]\d$/.test(str(a.preferred_time)) ? str(a.preferred_time) : '';
return { json: {
  valid: true, ai_ok: valid,
  intent: a.intent, urgency: a.urgency, language: a.language, summary: str(a.summary),
  name: input.name || str(a.name), phone: input.phone || str(a.phone), email: input.email || str(a.email),
  preferred_date: date, preferred_time: time,
  message: input.message, source: input.source, received_at: input.received_at,
} };

